          "prev_owners": [],
          "comment": "Won at Hamilton last month but has not threatened after slow starts in two runs since",
          "spotlight": "Hold-up performer who cashed in on reduced mark at Hamilton (5f, good) last month but he's not posed a threat after slow starts in two subsequent runs; four of his five wins have come at this track but he's not easy to predict and comes with risks attached.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "He's a bairn I know well as I trained his dam and granny, but he hasn't been easy to train. First time out this year he dropped Paul Mulrennan going to the start but, despite his quirks, he has an engine. I have an idea to run him on the all-weather to change the script a little. He's in grand form at home and we'll look at the 5f and 7f handicaps next week at Ayr. 12-09-22"
            }
          ],
