          "comment": "Seven-time winner but he's lost his way and needs a major revival back in trip",
          "spotlight": "Seven-time winner at up to 7f; well treated on his best form last year but he's been out of sorts after slow starts in last three runs; has plenty to prove and he needs a major revival back in trip.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "The word that best describes this horse is frustrating. He's hugely talented but so quirky. He hates the stalls and can throw his race away at the start. He's best at Musselburgh but he needs luck in running and doesn't always get it. He's a good 10lb or even 20lb better than his mark when things go his way and he's in the right frame of mind. He was off for six weeks before his penultimate run, which blew the cobwebs away, and he won at Newcastle on Monday on his all-weather debut, when things went his way and he just got up. 12-09-22"
            }
          ],
