          "comment": "Hat-trick seeker who scored in smooth style last time; big player again back up in trip",
          "spotlight": "Has form figures of 322411 since March and he justified support with a smooth success at Musselburgh (7f, good) 13 days ago; up another 4lb but he remains feasibly treated and his penultimate win was over this trip; big player.",
          "quotes": [
            {
              "date": "2023-11-19",
              "horse": "Keep Me Stable",
              "horse_id": "hrs_29228612",
              "race": "Bet £10 Get £40 At BetMGM Handicap",
              "race_id": "rac_11113531",
              "course": "Newcastle (AW)",
              "course_id": "crs_35178",
              "distance_f": "7",
              "distance_y": "1554",
              "quote": "We put Keep Me Stable out again because she came out of her last win in great form and we wanted to give her a chance. Tommie (Jakes, jockey) was taking 7lb off and when a filly is in good form you have to run them, you don't if they're not. She did it nicely and it was great. Being at Newcastle suits her because she can run against the rail and I think she likes the straight seven furlongs - Linda Perratt, trainer."
            }
          ],
