          "spotlight": "Well treated on old form but she missed last year and has had mixed results in three runs this season; ran a promising race behind Glasses Up over C&D in May but she was well held here last time, when the return to 1m5f shouldn't have been an issue; looks hard to weigh up at present and others are more solid.",
