          "comment": "Five-time AW winner but he's 0-10 on turf and has been well held last twice",
          "spotlight": "Completed a hat-trick off a similar mark at Southwell (1m4f, AW) in April but he's been well held in last two runs; bit to prove again at this new trip and he's 0-10 on turf; yard also runs Cascade Hall.",
          "quotes": [
            {
              "date": "2025-03-13",
              "horse": "Ana Emaraaty",
              "horse_id": "hrs_31725148",
              "race": "Gamble Responsibly At BetUK Classified Stakes (Div II)",
              "race_id": "rac_11572886",
              "course": "Newcastle (AW)",
              "course_id": "crs_35178",
              "distance_f": "10",
              "distance_y": "2242",
              "quote": "I just said to James [Callow] the owner there, that I actually thought Jimmy Sullivan had got away on us; he gave his a peach out in front, but Ana Emaraaty did all his best work in the last furlong. He relaxed real good for me early on, so it was perfect. The further he went, the better he went, and I wouldn't be surprised if he got a bit further as well - Paul Mulrennan, jockey speaking to Sky Sports Racing."
            }
          ],
          "stable_tour": [
            {
              "quote": "He'll be one for the all-weather. He's a bit of a lad and we've given him the summer off, and I expect he'll do well on the all-weather. Last year he didn't take too many races and I was guilty of running him too often. But I'm looking forward to training him during the winter and there are big bonuses to be won with horses like him. 02-10-24"
            }
          ],
