          "comment": "Won two small-field chases in the spring; unlikely to be allowed to dominate here, though",
          "spotlight": "Won two small-field Hereford chases (both 2m5f, good) from the front this spring and can be excused his latest run (pulled up in early stages with tack issues); should cope with today's drop back in trip but is very unlikely to be allowed to dominate here.",
