          "prev_owners": [
            {
              "owner": "Ollie Pears",
              "owner_id": "own_649168",
              "change_date": "2023-03-03"
            }
          ],
          "comment": "Made all in four-runner contest ten days ago and is now 3-3 over C&D; major player",
          "spotlight": "Back in good form this season, most recently when making all in four-runner C&D (good) contest ten days ago; 4lb higher today but now 3-3 over C&D and will be a tough nut to crack if able to dominate again.",
          "quotes": [
            {
              "date": "2023-09-30",
              "horse": "Max Of Stars",
              "horse_id": "hrs_34124223",
              "race": "Smokey Joe Juvenile Hurdle (GBB Race)",
              "race_id": "rac_11032996",
              "course": "Market Rasen",
              "course_id": "crs_910",
              "distance_f": "16.5",
              "distance_y": "3645",
              "quote": "Max Of Stars is a good mare and that's the best she's run. She's always been a keen-going sort, but she's never finished better than she did today. She's off to Wetherby now (for the Listed Wensleydale Juvenile Hurdle on November 3rd) and then she'll have a break. I can see her going back on the Flat in March before going back over hurdles and then we're thinking about maybe going over fences. She's a horse with a massive amount of upside and a lot of options - Ollie Pears, trainer."
            },
            {
              "date": "2023-09-09",
              "horse": "Max Of Stars",
              "horse_id": "hrs_34124223",
              "race": "Lee Pollard 60th Birthday Handicap Hurdle",
              "race_id": "rac_11009778",
              "course": "Stratford",
              "course_id": "crs_1742",
              "distance_f": "16.5",
              "distance_y": "3590",
              "quote": "That's a big chunk of an allowance to get [18lb]. Max Of Stars does have Flat speed but couldn't win on the Flat because she was too keen. She was keen today as well but enjoys jumping and is big for a 3yo filly. At Newton Abbot she ran away with me and had everything burned off by halfway. To be fair to them the opposition is fairly exposed today and she was the unexposed one - Brian Hughes, rider, speaking to RacingTV."
            }
          ],
