              "horse": "India Love",
              "horse_id": "hrs_53539416",
              "race": "Juddmonte EBF Fillies' Restricted Novice Stakes (Bands A-D) (EBF Qual') (GBB/IRE Incentive Race)",
              "race_id": "rac_11637470",
              "course": "York",
              "course_id": "crs_2782",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "India Love has been keen at home and showed plenty of enthusiasm, so cover was essential. She's got loads of speed and will get faster. Once she learns to race properly in a stronger race, she'll be a really nice filly. She was well-bought and does everything right at home - David Egan, jockey."
