          "comment": "Ended Irish campaign right out of form and trailed both runs this year for new connections",
          "spotlight": "Won two in a row over 6f last summer but ended that Irish campaign right out of form and he's trailed on both starts this year for new connections.",
          "quotes": [
            {
              "date": "2024-08-05",
              "horse": "Mehmar",
              "horse_id": "hrs_30208255",
              "race": "Fern Lane Handicap",
              "race_id": "rac_11363599",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "6",
              "distance_y": "1305",
              "quote": "Mehmar is going the right way and is making up for lost time. Colin said he's very straightforward, pings the gates. I was lucky to find this race for him, with not so many runners. It ticks another box and gets the second run out of the way. We might go to the drawing board now and make a plan - Michael O'Callaghan, trainer."
            },
            {
              "date": "2024-07-13",
              "horse": "Mehmar",
              "horse_id": "hrs_30208255",
              "race": "Ardboyne Hotel Maiden",
              "race_id": "rac_11342838",
              "course": "Navan",
              "course_id": "crs_5018",
              "distance_f": "6",
              "distance_y": "1280",
              "quote": "Mehmar had good form at two. It was a fair ask after that long off the track. Michael thought he would come on for it, but he picked up and was very professional. He's a very strong horse and handles that quick ground well. You would hope he will keep progressing - Colin Keane, rider."
            }
          ],
