          "comment": "Doncaster win (1m, good to firm) latest is easily his best run on turf; 11lb below AW mark",
          "spotlight": "Four AW wins from December to March and another on turf at Doncaster (1m, good to firm) 16 days ago; that was easily his best run on turf but it's possible he now has more to offer in this sphere; up 4lb but that's 11lb below his AW figure.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "He went to Newmarket recently as something of a big hope, but it was his first run on turf and the ground was holding, while Richard Kingscote thought he was very green about it all. He thought he'd come on mentally for that, while he's got a great action so probably wants the top side of good ground. He works like a good horse and I'd like to think he could be a Royal Ascot horse for the Britannia or Golden Gates Stakes. We'll aim for a mile race on fast ground before that and he's quite similar in terms of ability to Outgate, who was a star for us before being sold to Hong Kong. 02-05-24"
            }
          ],
