          "comment": "Neck second over C&D in April; failed to fire sole start since; pretty reliable normally",
          "spotlight": "Two of his six wins have been at this track (including this race two years ago) where he was a strong-finishing neck second over C&D (good to firm) in April; he failed to fire, however, in a slowly run race back over C&D six weeks ago on sole start since; pretty reliable normally.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "He has now won four of his 12 races, including last time out at Windsor earlier this month. I sent him there thinking he should be competitive but I was pleasantly surprised how easily he won. The handicapper has not been too harsh, rising him 8lb to a mark of 88 and you would hope he can win again off that. He has clearly improved from last season and this big scopey individual could have more to offer. All being well he runs next week Windsor, again over 1m2f but in a Class 3 this time. 25-05-22"
            }
          ],
