              "distance_f": "10",
              "distance_y": "2200",
              "quote": "Wadacre Gomez is very straightforward and I'm a passenger really on him. The hardest part is getting him out of the gates and from then on, he pretty much does it himself, sets his own fractions. The Johnston horses have that tough trait in them and they keep going when they need too - Billy Loughnane, jockey, speaking to Racing TV."
