          "comment": "2025 record reads 1314 and he ran creditably last time too; should go well again",
          "spotlight": "One win in his first 16 starts but record since returning in April reads 1314, with the wins at Nottingham (1m2f) and Leicester (1m4f); gamely made most in the latter and again set the pace when running creditably at Goodwood (1m4f) on latest start, ending up alongside Morcar; should go well again.",
          "quotes": [],
