          "comment": "2024 C&D win; made all under M Paetel over 1m2f in smallish fields on his last two starts",
          "spotlight": "One of last season's two wins was over C&D; with new yard this term and he's been in top form on his last two starts, making all under Mason Paetel over 1m2f in smallish fields at Leicester and Epsom; back up another 4lb after the game display 12 days ago and this is his first Flat handicap above Class 5, but he needs major respect.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "We bought him at the sales in November for a syndicate who wanted a horse to have fun with. He tends to be over-exuberant in his races and we put a hood on him first time out. I'd love to be telling you that he's relaxed, but he jumps the stalls so fast that he's very much there to be got at if he doesn't quite finish his race. He should be fun for the syndicate and hopefully he'll be winning at his level. His second last time at Nottingham was quite a good run - the winner was well handicapped - and he went back there on Tuesday and ran well again. 30-04-25"
            }
          ],
