          "comment": "Never counted on belated chase debut last month; hard to fancy entering handicap company",
          "spotlight": "Dual-purpose; without a win over hurdles since 2022; belated chase debut last month when never counting in 2m Roscommon handicap; hard to make a case for now entering handicap company.",
          "quotes": [
            {
              "date": "2022-11-14",
              "horse": "Wajaaha",
              "horse_id": "hrs_10465511",
              "race": "Sky Sports Racing Sky 415 Selling Hurdle",
              "race_id": "rac_10710570",
              "course": "Plumpton",
              "course_id": "crs_1144",
              "distance_f": "16",
              "distance_y": "3495",
              "quote": "I'd have been disappointed to lose Wajaaha and delighted we were able to keep him. He's a fun horse, despite having a few issues with his back. He's got lots of ability and carried a nice rating on the Flat. Charles Byrnes, trainer"
            },
            {
              "date": "2020-08-21",
              "horse": "Wajaaha",
              "horse_id": "hrs_10465511",
              "race": "KilbegganRaces.com Novice Hurdle",
              "race_id": "rac_9943531",
              "course": "Kilbeggan",
              "course_id": "crs_5278",
              "distance_f": "18",
              "distance_y": "3993",
              "quote": "They went real hard up front on that ground. There was no way they were going to get home. It's holding ground. It's nice to sit on these type of horses. Wajaaha jumped and travelled like the best horse - Kevin Brouder, rider"
            },
            {
              "date": "2020-06-29",
              "horse": "Wajaaha",
              "horse_id": "hrs_10465511",
              "race": "Fedamore Handicap",
              "race_id": "rac_9899552",
              "course": "Limerick",
              "course_id": "crs_4888",
              "distance_f": "12",
              "distance_y": "2640",
              "quote": "He had a great draw today compared to a bad draw the last day at Roscommon. There might be something for him at Galway. The ground was perfect for him today, he handles a slight dig in it - Charles Byrnes, trainer of Wajaaha"
            },
            {
              "date": "2020-03-02",
              "horse": "Wajaaha",
              "horse_id": "hrs_10465511",
              "race": "Kids Go Racing Handicap Hurdle",
              "race_id": "rac_9786439",
              "course": "Leopardstown",
              "course_id": "crs_4862",
              "distance_f": "16",
              "distance_y": "3520",
              "quote": "Wujaaha had a nice run at Naas and he has come forward a good bit. He's a bit temperamental but when he gets things his own way he looks good. He'll tip away in handicap hurdles - Charles Byrnes, trainer"
            }
          ],
