              "distance_f": "7",
              "distance_y": "1540",
              "quote": "That was very impressive and maybe the cut in the ground today helped, but also the extra furlong. Rion Rubette had been running over a shorter trip and she was unlucky to meet a good horse the last day. On her Curragh run, I thought she might get through and win but I thought she might only win by half a length or a length - Michael Butler, trainer."
