          "comment": "Won last three incl' heritage handicap at York at 1m6f, trip surely too sharp on return",
          "spotlight": "Had an excellent campaign last season, winning his last three runs in a row (two on Flat one over hurdles); those Flat wins, including a heritage handicap at York, came at 1m6f and 2m; this will surely be too sharp a test on his return.",
          "quotes": [
            {
              "date": "2024-10-06",
              "horse": "Extensio",
              "horse_id": "hrs_21878381",
              "race": "Racing TV Handicap Hurdle",
              "race_id": "rac_11419174",
              "course": "Tipperary",
              "course_id": "crs_5252",
              "distance_f": "16",
              "distance_y": "3570",
              "quote": "Extensio had so little experience and topweight, but I had a super horseman on him. It was a big call to run him here under topweight but unfortunately that's what the programme dictated. We couldn't run in those bigger hurdle races without having three runs, so we had to do what we did today and it came off - Pat O['Donnell, trainer"
            },
            {
              "date": "2024-08-21",
              "horse": "Extensio",
              "horse_id": "hrs_21878381",
              "race": "Sky Bet Stayers Handicap (Heritage Handicap)",
              "race_id": "rac_11348844",
              "course": "York",
              "course_id": "crs_2782",
              "distance_f": "16.5",
              "distance_y": "3576",
              "quote": "I said to Joey (Sheridan) to be the last to challenge and he was. We said that if Extensio won today we'd work back from Royal Ascot. It's a big shout with a family horse, but we're not going there for the scenery and we're entitled to aim there - Pat O'Donnell, trainer."
            },
            {
              "date": "2024-07-10",
              "horse": "Extensio",
              "horse_id": "hrs_21878381",
              "race": "Fairyhouse Summer BBQ Rated Race",
              "race_id": "rac_11340810",
              "course": "Fairyhouse",
              "course_id": "crs_4732",
              "distance_f": "14",
              "distance_y": "3080",
              "quote": "Extensio blew the house down after his run here the last day and I was worried about how much it took out of him, but we got it right. He continues to improve and we will look at the Cesarewitch at Newmarket - Pat O'Donnell, trainer"
            },
            {
              "date": "2023-09-07",
              "horse": "Extensio",
              "horse_id": "hrs_21878381",
              "race": "John O'Brien Memorial Tipperary Cup Handicap",
              "race_id": "rac_11036428",
              "course": "Clonmel",
              "course_id": "crs_4602",
              "distance_f": "16.5",
              "distance_y": "3664",
              "quote": "Extensio could be a proper horse looking at that - Pat O'Donnell, trainer."
            },
            {
              "date": "2023-08-08",
              "horse": "Extensio",
              "horse_id": "hrs_21878381",
              "race": "Coast To Curragh On August, 26th Maiden Hurdle",
              "race_id": "rac_11012118",
              "course": "Roscommon",
              "course_id": "crs_5096",
              "distance_f": "15.5",
              "distance_y": "3358",
              "quote": "I'm delighted. I've ridden a point-to-point winner and that's my sixth ride on the track, first over hurdles. Extensio jumped like a buck, everything went smoothly - Pat Gleeson, jockey, talking to Racing TV."
            },
            {
              "date": "2022-07-16",
              "horse": "Extensio",
              "horse_id": "hrs_21878381",
              "race": "Kildare Village Ladies Derby Handicap",
              "race_id": "rac_10624952",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "12",
              "distance_y": "2640",
              "quote": "Extensio had shown form early, he was a very weak yearling, but he was a resolute galloper - Pat O'Donnell, trainer."
            }
          ],
